inputs.common/ai_regional_objectives/00_ai_regi:
# Generic objectives
ai_regional_objective_acquire_states = {
	stances = { stance_conquer_region stance_colonize_region }

	possible = {
		scope:target_region = {
			any_scope_state = {
				aro_is_acquire_states_candidate = yes
			}
		}
	}

	on_create = {
		scope:target_region = {
			ordered_scope_state = {
				limit = {
					aro_is_acquire_states_candidate = yes
				}
				order_by = "root.military_reach(this)"
				max = 3
				check_range_bounds = no
				root = {
					add_to_variable_map = {
						name = aro_acquire_states_targets
						key = prev.state_region
						value = scope:target_region
					}
				}
			}
		}
	}

	complete = {
		scope:target_region = {
			any_scope_state = {
				owner = root
				aro_is_acquire_states_target = yes
			}
		}
	}

	invalid = {
		NOT = {
			scope:target_region = {
				any_scope_state = {
					NOT = { owner = root }
					aro_is_acquire_states_target = yes
				}
			}
		}
	}

	state_target = {
		scope:target_state = {
			NOT = { owner = root }
			aro_is_acquire_states_target = yes
		}
	}

	on_complete = {
		scope:target_region = {
			every_scope_state = {
				limit = {
					aro_is_acquire_states_target = yes
				}
				root = {
					remove_from_variable_map = {
						name = aro_acquire_states_targets
						key = prev.state_region
					}
				}
			}
		}
	}

	on_invalid = {
		scope:target_region = {
			every_scope_state = {
				limit = {
					aro_is_acquire_states_target = yes
				}
				root = {
					remove_from_variable_map = {
						name = aro_acquire_states_targets
						key = prev.state_region
					}
				}
			}
		}
	}

	weight = {
		value = 10

		if = {
			limit = { scope:target_stance = srs:stance_conquer_region }
			add = 10
		}
	}
}

ai_regional_objective_recover_claims = {
	stances = { stance_conquer_region stance_colonize_region stance_protect_region }

	possible = {
		scope:target_region = {
			any_scope_state = {
				has_claim_by = root
			}
		}
	}

	complete = { # TODO: check for success/failure?
		scope:target_region = {
			NOT = {
				any_scope_state = {
					has_claim_by = root
				}
			}
		}
	}

	state_target = {
		scope:target_state = {
			has_claim_by = root
		}
	}

	weight = {
		value = 10

		if = {
			limit = {
				scope:target_stance = {
					OR = {
						this = srs:stance_conquer_region
						this = srs:stance_colonize_region
					}
				}
			}
			add = 90 # Prioritize if available
		}
	}
}

ai_regional_objective_subjugate_country = {
	stances = { stance_conquer_region stance_colonize_region }

	possible = {
		scope:target_region = {
			any_scope_country = {
				is_local_country = scope:target_region
				is_subject = no
				country_rank < root.country_rank
				ai_subject_value:root > 0
			}
		}
	}

	on_create = {
		scope:target_region = {
			ordered_scope_country = {
				limit = {
					is_local_country = scope:target_region
					is_subject = no
					country_rank < root.country_rank
				}
				order_by = ai_subject_value:root
				position = 0
				save_temporary_scope_as = aro_subjugate_country_target
			}
		}
		add_to_variable_map = {
			name = aro_subjugate_country_map
			key = scope:target_region
			value = scope:aro_subjugate_country_target
		}
	}

	complete = {
		"variable_map(aro_subjugate_country_map|scope:target_region)" ?= {
			is_subject_of = root
		}
	}

	invalid = {
		NOT = {
			"variable_map(aro_subjugate_country_map|scope:target_region)" ?= {
				is_local_country = scope:target_region
				any_scope_state = { region = scope:target_region }
			}
		}
	}

	country_target = {
		"variable_map(aro_subjugate_country_map|scope:target_region)" ?= scope:target_country
	}

	on_complete = {
		remove_from_variable_map = {
			name = aro_subjugate_country_map
			key = scope:target_region
		}
	}

	on_invalid = {
		remove_from_variable_map = {
			name = aro_subjugate_country_map
			key = scope:target_region
		}
	}

	weight = {
		value = 10

		if = {
			limit = {
				scope:target_stance = srs:stance_colonize_region
			}
			add = 10
		}
	}
}

ai_regional_objective_befriend_countries = {
	stances = { stance_protect_region }

	possible = {
		scope:target_region = {
			any_scope_country = {
				aro_is_befriend_countries_target = { REGION = scope:target_region }
			}
		}
	}

	on_create = {
		save_temporary_scope_value_as = {
			name = aro_befriend_countries_num
			value = {
				scope:target_region = {
					every_scope_country = {
						limit = {
							aro_is_befriend_countries_target = { REGION = scope:target_region }
						}
						add = 1
					}
				}
				min = 0
			}
		}
		add_to_variable_map = {
			name = aro_befriend_countries_map
			key = scope:target_region
			value = scope:aro_befriend_countries_num
		}
	}

	complete = {
		scope:target_region = {
			any_scope_country = {
				aro_is_befriend_countries_target = { REGION = scope:target_region }
				count < "root.variable_map(aro_befriend_countries_map|scope:target_region)"
			}
		}
	}

	country_target = {
		scope:target_country = {
			aro_is_befriend_countries_target = { REGION = scope:target_region }
		}
	}

	on_complete = {
		remove_from_variable_map = {
			name = aro_befriend_countries_map
			key = scope:target_region
		}
	}

	on_invalid = {
		remove_from_variable_map = {
			name = aro_befriend_countries_map
			key = scope:target_region
		}
	}

	weight = {
		value = 10
	}
}

ai_regional_objective_protect_country = {
	stances = { stance_protect_region }

	possible = {
		scope:target_region = {
			any_scope_country = {
				is_local_country = scope:target_region
				country_rank < root.country_rank
				is_subject = no
				any_neighbouring_state = {
					owner = {
						has_diplomatic_pact = {
							who = root
							type = rivalry
						}
					}
				}
			}
		}
	}

	on_create = {
		scope:target_region = {
			random_scope_country = {
				limit = {
					is_local_country = scope:target_region
					country_rank < root.country_rank
					is_subject = no
					any_neighbouring_state = {
						owner = {
							has_diplomatic_pact = {
								who = root
								type = rivalry
							}
						}
					}
				}
				save_temporary_scope_as = aro_protect_country_target
			}
		}
		add_to_variable_map = {
			name = aro_protect_country_map
			key = scope:target_region
			value = scope:aro_protect_country_target
		}
	}

	complete = {
		"variable_map(aro_protect_country_map|scope:target_region)" ?= {
			OR = {
				has_treaty_alliance_with = { TARGET = root }
				has_treaty_defensive_pact_with = { TARGET = root }
				has_treaty_guarantee_independence_with = { TARGET = root }
				is_subject_of = root
			}
		}
	}

	invalid = {
		NOT = {
			"variable_map(aro_protect_country_map|scope:target_region)" ?= {
				is_local_country = scope:target_region
				any_scope_state = { region = scope:target_region }
			}
		}
	}

	country_target = {
		"variable_map(aro_protect_country_map|scope:target_region)" ?= scope:target_country
	}

	on_complete = {
		remove_from_variable_map = {
			name = aro_protect_country_map
			key = scope:target_region
		}
	}

	on_invalid = {
		remove_from_variable_map = {
			name = aro_protect_country_map
			key = scope:target_region
		}
	}

	weight = {
		value = 10
	}
}

inputs.common/ai_strategies/00_default_strategy:
# This is a special strategy that sets the default values for different AI scores
# All AIs always load data from this strategy, which can then be either added to or overridden by data from its other strategies

ai_strategy_default = {
	icon = "gfx/interface/icons/ai_strategy_icons/placate_population.dds" # Never shown

	# If this trigger evaluates to true for any active strategy, the AI will try to form a power bloc
	# Empty trigger counts as evaluating false in this specific case
	will_form_power_bloc = {}

	# If this trigger evaluates to true for any active strategy, the AI will incorporate scope:target_state if it can afford it and if it's the highest value valid candidate
	# Empty trigger counts as evaluating false in this specific case
	# Capitals bypass this and start incorporating immediately if possible
	# Using this in a different strategy is inclusive, only one needs to return true
	# root = country, scope:target_state = the state being considered
	will_incorporate_state = {
		trigger_if = { # Colonies have a different behaviour
			limit = {
				country_is_colonial_or_company = yes
			}
			scope:target_state = { ai_colony_will_incorporate_state = yes }
		}
		trigger_else_if = { # Default behaviour
			limit = {
				scope:target_state = { ai_will_incorporate_state = yes }
			}
			always = yes
		}
		trigger_else = { # Content
			OR = {
				AND = {
					has_journal_entry = je_the_algerian_departements
					scope:target_state = {
						OR = {
							state_region = s:STATE_ORAN
							state_region = s:STATE_ALGIERS
							state_region = s:STATE_CONSTANTINE
						}
					}
				}
				AND = {
					has_journal_entry = je_french_natural_borders
					scope:target_state = {
						OR = {
							state_region = s:STATE_WALLONIA
							state_region = s:STATE_FLANDERS
							state_region = s:STATE_RHINELAND
							state_region = s:STATE_NORTH_RHINE
						}
					}
				}
				AND = {
					has_journal_entry = je_matter_of_hungary
					scope:target_state = {
						state_region = { is_homeland = cu:hungarian }
					}
				}
				AND = {
					has_journal_entry = je_la_trinitaria
					scope:target_state = {
						state_region = s:STATE_SANTO_DOMINGO
					}
				}
				AND = {
					has_journal_entry = je_colonize_korea
					scope:target_state = {
						is_in_geographic_region = geographic_region_korea
					}
				}
				AND = {
					has_journal_entry = je_tp_pool_develop_frontier
					scope:target_state = {
						OR = {
							has_variable = rus_develop_frontier_unincorporated_state
							AND = {
								root = { has_variable = tp_siberia_frontier_target_gdp }
								is_in_geographic_region = geographic_region_siberia
							}
							AND = {
								root = { has_variable = tp_central_asia_frontier_target_gdp }
								is_in_geographic_region = geographic_region_central_asia
							}
							AND = {
								root = { has_variable = tp_caucasus_frontier_target_gdp }
								is_in_geographic_region = geographic_region_caucasus_old
							}
						}
					}
				}
				AND = {
					has_journal_entry = je_tp_tsar_crown_of_perfection
					NOT = { has_variable = je_tp_tsar_crown_of_perfection_button_4_complete }
					scope:target_state = { is_in_same_market_area = root.capital }
				}
				AND = {
					has_journal_entry = je_russification
					scope:target_state = { is_in_geographic_region = geographic_region_russia_western_borderlands }
					any_state_in_russia_western_borderlands = {
						owner ?= c:RUS
						percent < je_russification_region_goal_percent
					}
				}
			}
		}
	}

	# These are the tax levels the AI will try to stay within, though it can go above max tax level if in a financial emergency
	# Using a different value in a strategy will override these values
	desired_tax_level = medium
	max_tax_level = high
	min_tax_level = low

	# The AI will avoid getting this much infamy unless it's a wargoal it really wants
	# Using a different value in a strategy will override this value
	undesirable_infamy_level = {
		value = 50
	}

	# The AI will never deliberately add wargoals that will bring its infamy this high
	# Using a different value in a strategy will override this value
	unacceptable_infamy_level = {
		value = 100
	}

	# How much is the AI's diplomatic acceptance, etc affected by government ideological differences
	# Using a different value in a strategy will function multiplicatively
	ideological_opinion_effect_mult = {
		value = 1.0
	}

	# Chance each day that the AI will stop enacting a law that is going to spark a civil war (1 aversion should translate into ~25% chance of avoiding a civil war)
	# Using a different value in a strategy will override this value
	revolution_aversion = {
		value = 5

		# Ottomans should avoid getting into revolutions before they deal with Egypt
		if = {
			limit = {
				has_journal_entry = je_sick_man_syria
				game_date < 1845.1.1
			}
			add = 100
		}

		if = {
			limit = {
				has_journal_entry = je_the_grand_collapse
			}
			add = 100
		}
	}

	# If base chance for law to pass is below this, don't enact it
	# Using a different value in a strategy will override this value
	min_law_chance_to_pass = {
		value = 50
	}

	# The chance that the AI will negotiate with an IG when trying to enact a specific law, 1 = 100%
	# Using this value in other strategies will function additively
	# root = country
	# scope:law = law type being enacted
	# scope:interest_group = IG to negotiate with
	# scope:amenability = IG amenability to negotiation divided by MAX_AMENABILITY (ie, if MAX_AMENABILITY is 100 and IG amenability is 50, this value will be 0.5)
	# scope:advance_chance = Chance to advance law enactment
	# scope:stall_chance = Chance for law enactment to stall
	negotiation_chance = {
		value = 0

		if = {
			limit = {
				scope:interest_group ?= {
					amenability_level != 4
				}
			}
			value = scope:amenability

			add = scope:stall_chance

			if = {
				limit = {
					ai_has_reasons_to_not_oppose_law = yes
				}
				multiply = 2
			}

			subtract = {
				value = scope:advance_chance
				multiply = 2
			}
		}

		max = 1
	}

	# How progressive is the AI willing to be when passing laws
	# Using a different value in a strategy will override this value
	max_progressiveness = {
		value = 25
	}

	# How regressive is the AI willing to be when passing laws
	# Using a different value in a strategy will override this value
	max_regressiveness = {
		value = 25
	}

	# Added to willingness to support a country in diplomatic plays
	# Using this value in other strategies will function additively
	# root = supporting country doing the AI evaluation
	# scope:country = country we're evaluating support for (either initiator or target)
	# scope:enemy_country = the opposing side's leader
	# scope:diplomatic_play_type = the type of diplomatic play
	# scope:is_initiator = bool, set to true if evaluating support for initiator, false if target
	# NOTE: You need to include a description when adding values here so there are correct tooltips, this is different from most of ai strategy data!
	diplomatic_play_support = {
		value = 0

		add = {
			desc = "DIPLOMATIC_REPUTATION_REASON"
			value = "scope:country.modifier:country_diplomatic_reputation_add"
			if = {
				limit = {
					root = {
						NOT = {
							has_law_or_variant = law_type:law_council_republic
						}
					}
					scope:country = {
						has_law_or_variant = law_type:law_council_republic
					}
				}
				subtract = {
					value = "scope:country.modifier:country_other_country_socialist_government_hostility_impact_add"
					multiply = {
						value = 1
						add = "scope:country.modifier:country_other_country_socialist_government_hostility_impact_mult"
					}
				}
				subtract = {
					value = "scope:country.modifier:country_other_country_socialist_government_hostility_impact_add"
					multiply = {
						value = 1
						add = "scope:country.modifier:country_other_country_socialist_government_hostility_impact_mult"
					}
				}
			}
		}

		### German Leadership War
		if = {
			# Non-Germans should stay out of the leadership war unless they have a good reason to intervene
			limit = {
				scope:diplomatic_play_type = play_type:dp_leadership_germany
				NOR = {
					country_has_primary_culture = cu:north_german
					country_has_primary_culture = cu:south_german
				}
			}

			if = {
				limit = {
					NOR = {
						any_scope_treaty = {
							binds = scope:country
							any_scope_article = {
								has_type = alliance
							}
						}
						AND = {
							NOT = { exists = scope:is_initiator }
							OR = {
								any_scope_treaty = {
									binds = scope:country
									any_scope_article = {
										has_type = defensive_pact
									}
								}
								any_scope_treaty = {
									binds = scope:country
									any_scope_article = {
										has_type = guarantee_independence
									}
								}
							}
						}
					}

					scope:enemy_country = {
						NOR = {
							play_participant_has_war_goal_of_type_against = {
								type = conquer_state
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = make_protectorate
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = liberate_country
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = liberate_subject
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = transfer_subject
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = take_treaty_port
								target = scope:country
							}
						}
					}
				}

				add = {
					value = -200
					desc = "german_leadership_neutrality"
				}
			}
		}

		### Schleswig War
		if = {
			limit = {
				NOR = {
					country_has_primary_culture = cu:north_german
					country_has_primary_culture = cu:south_german
				}
				OR = {
					AND = {
						scope:country = {
							is_oppressor_of_schleswig_holstein = yes
						}
						scope:enemy_country = {
							has_journal_entry = je_schleswig_holstein_question
						}
					}
					AND = {
						scope:enemy_country = {
							is_oppressor_of_schleswig_holstein = yes
						}
						scope:country = {
							has_journal_entry = je_schleswig_holstein_question
						}
					}
				}
			}

			if = {
				limit = {
					NOR = {
						any_scope_treaty = {
							binds = scope:country
							any_scope_article = {
								has_type = alliance
							}
						}
						AND = {
							NOT = { exists = scope:is_initiator }
							OR = {
								any_scope_treaty = {
									binds = scope:country
									any_scope_article = {
										has_type = defensive_pact
									}
								}
								any_scope_treaty = {
									binds = scope:country
									any_scope_article = {
										has_type = guarantee_independence
									}
								}
							}
						}
					}

					scope:enemy_country = {
						NOR = {
							play_participant_has_war_goal_of_type_against = {
								type = conquer_state
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = make_protectorate
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = liberate_country
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = take_treaty_port
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = enforce_treaty_article
								target = scope:country
							}
						}
					}
				}
				add = {
					value = -100
					desc = "je_schleswig_holstein_question"
				}
			}
		}

		### Ottomans vs Egypt - Great Powers pick sides
		if = {
			limit = {
				OR = {
					AND = {
						scope:country = { c:TUR ?= this }
						scope:enemy_country = { c:EGY ?= this }
					}
					AND = {
						scope:country = { c:EGY ?= this }
						scope:enemy_country = { c:TUR ?= this }
					}
				}
				c:TUR ?= {
					OR = {
						has_journal_entry = je_sick_man_syria
						has_journal_entry = je_sick_man_egypt
						has_journal_entry = je_veiled_protectorate
					}
				}
			}

			if = {
				limit = {
					has_variable = veiled_protectorate_support_ottomans
					OR = {
						AND = {
							NOT = { exists = scope:is_initiator }
							scope:enemy_country = { c:TUR ?= this }
						}
						AND = {
							exists = scope:is_initiator
							scope:country = { c:TUR ?= this }
						}
					}
				}

				add = {
					value = 100
					desc = "veiled_protectorate_ottomans_support"
				}
			}
			else_if = {
				limit = {
					has_variable = veiled_protectorate_support_egypt
					OR = {
						AND = {
							NOT = { exists = scope:is_initiator }
							scope:enemy_country = { c:EGY ?= this }
						}
						AND = {
							exists = scope:is_initiator
							scope:country = { c:EGY ?= this }
						}
					}
				}

