	# How much does the AI desire a state owned by another country
	# Using this value in other strategies will function additively
	# root = country
	# scope:target_state = state
	# scope:target_country = state owner
	treaty_port_value = {
		value = 0

		if = {
			limit = {
				# Because the target state in a treaty article is not actually the treaty port state, we need to check the entire state region
				scope:target_state = {
					state_region = {
						any_scope_state = {
							is_treaty_port = yes
							OR = {
								owner = { is_subject_of = ROOT }
								owner = ROOT
							}
						}
					}
				}
			}
			add = 40
		}

		if = {
			limit = {
				NOT = { is_country_type = unrecognized }
				scope:target_country = { is_country_type = unrecognized }
				NOT = { is_adjacent_to_country = scope:target_country } # No interest in treaty ports right next to our lands
				OR = {
					scope:target_country = {
						has_diplomatic_pact = {
							who = root
							type = embargo
						}
					}
					AND = {
						has_strategy = ai_strategy_economic_imperialism
						"mutual_trade_value_with_country(root)" >= 1000
						OR = {
							has_attitude = {
								who = scope:target_country
								attitude = belligerent
							}
							has_attitude = {
								who = scope:target_country
								attitude = domineering
							}
							has_attitude = {
								who = scope:target_country
								attitude = antagonistic
							}
						}
					}
				}
			}

			add = {
				value = 5

				add = {
					value = scope:target_state.state_population
					divide = 200000
					max = 10
				}

				add = {
					value = scope:target_state.gdp
					divide = 200000
					max = 10
				}

				if = {
					limit = {
						any_scope_building = {
							is_building_type = building_trade_center
							level > 0
						}
					}
					add = 5
				}

				if = {
					limit = {
						has_strategic_adjacency = scope:target_state
					}
					multiply = 1.50
				}

				if = {
					limit = {
						scope:target_state = { is_incorporated = no	}
					}
					multiply = 0.25
				}
			}
		}

		if = {
			limit = {
				has_journal_entry = je_opium_wars
				scope:target_country = {
					has_variable = opium_wars_target
				}
				scope:target_state = {
					NOT = { state_region = s:STATE_FORMOSA }
				}
			}
			add = 100
		}

		if = { #Carving up China
			limit = {
				should_carve_up_china = yes
				scope:target_state = {
					owner = { is_country_type = unrecognized }
					OR = {
						region = sr:region_north_china
						region = sr:region_south_china
						is_in_geographic_region = geographic_region_manchuria_old
					}
				}
			}
			add = 100
		}

		if = {
			limit = {
				# Because the target state in a treaty article is not actually the treaty port state, we need to check the entire state region
				scope:target_state = {
					NOT = {
						state_region = {
							any_scope_state = {
								is_treaty_port = yes
								OR = {
									owner = { is_subject_of = ROOT }
									owner = ROOT
								}
							}
						}
					}
				}
			}

			if = {
				limit = { has_treaty_port_in_market = scope:target_country.market }
				multiply = 0.25
			}

			# Don't want treaty ports on countries in our market
			if = {
				limit = {
					market_capital.market ?= scope:target_country.market_capital.market
				}
				multiply = 0.0
			}

			# Not worth doing against very small markets
			if = {
				limit = {
					scope:target_country = {
						gdp < 2000000
					}
				}
				multiply = 0
			}

			if = {
				limit = {
					scope:target_country = {
						any_scope_treaty = {
							binds = root
							any_scope_article = {
								has_type = trade_privilege
								source_country = scope:target_country
							}
						}
					}
				}
				multiply = 0.25
			}

			if = {
				limit = {
					NOT = { can_reach_target_state_to_coerce = { TARGET_STATE = scope:target_state } }
				}
				multiply = 0
			}
		}

		min = 0
		max = 100
	}

	# How much does the AI desire another country as their subject
	# Using this value in other strategies will function additively
	# root is the AI doing the evaluation, scope:target_country is prospective subject
	subject_value = {
		value = 0

		# PUT ALL REGULAR SUBJECT SCORES INSIDE THE BELOW IF STATEMENT TO PREVENT AI FROM TAKING UNREACHABLE SUBJECTS
		if = {
			limit = {
				OR = {
					scope:target_country = { is_subject_of = root }
					can_reach_target_country_to_subjugate = { TARGET_COUNTRY = scope:target_country }
				}
			}

			if = {
				limit = {
					ai_is_regional_objective_subjugate_target = { TARGET = scope:target_country }
				}
				add = ai_regional_objective_subject_value
			}

			add = {
				if = {
					limit = {
						OR = {
							scope:target_country = { is_subject_of = root }
							has_attitude = {
								who = scope:target_country
								attitude = protective
							}
							has_attitude = {
								who = scope:target_country
								attitude = domineering
							}
