							scope:target_country = {
								c:UZH ?= THIS
							}
						}
						AND = {
							exists = c:OZH
							scope:target_country = {
								c:OZH ?= THIS
							}
						}
						AND = {
							exists = c:KOK
							scope:target_country = {
								c:KOK ?= THIS
							}
						}
						AND = {
