								has_state_in_state_region = STATE_KABUL
								has_state_in_state_region = STATE_HERAT
								has_state_in_state_region = STATE_KANDAHAR
							}
						}
					}
				}
				add = 50
			}

			if = {
				limit = {
					OR = {
						AND = {
							OR = {
								has_journal_entry = je_north_german_unification
								has_journal_entry = je_german_unification
							}
							scope:target_country = {
								country_has_primary_culture = cu:north_german
								NOT = {
									is_in_same_power_bloc = ROOT
								}
							}
						}
						AND = {
							OR = {
								has_journal_entry = je_north_german_unification
								has_journal_entry = je_german_unification
							}
							scope:target_country = {
								country_has_primary_culture = cu:south_german
								NOT = {
									is_in_same_power_bloc = ROOT
								}
							}
						}
					}
