						NOT = {
							is_in_same_power_bloc = ROOT
						}
					}
				}
				add = 50
			}

			if = {
				limit = {
					lenient_ai_behavior_trigger = yes
				}
				multiply = 0.5
			}

			if = {
				limit = {
					AND = {
						has_radical_leftist_government = no
						scope:target_country = {
							has_radical_leftist_government = yes
						}
					}
				}
				multiply = {
					value = 1
					subtract = {
						value = 1
						subtract = 1.5
						multiply = {
							value = 1
							add = scope:target_country.modifier:country_other_country_socialist_government_hostility_impact_mult
						}
					}
					min = 0
				}
			}

			if = {
