						subtract = 1.5
						multiply = {
							value = 1
							add = scope:target_country.modifier:country_other_country_socialist_economy_hostility_impact_mult
						}
					}
					min = 0
				}
			}
		}

		if = {
			limit = {
				has_secret_goal = {
					who = scope:target_country
					secret_goal = dominate
				}
			}

			min = 25
		}

		# AI should open up large isolationist powers, not subjugate them
		if = {
			limit = {
				has_strategy = ai_strategy_economic_imperialism
				scope:target_country = {
					has_law_or_variant = law_type:law_isolationism
