							attitude = loyal
						}
						has_attitude = {
							who = scope:overlord
							attitude = cooperative
						}
					}
				}
				value = 10
			}
			if = {
				limit = {
					has_attitude = {
						who = scope:overlord
						attitude = cautious
					}
				}
				value = -25
			}
			if = {
				limit = {
					OR = {
						has_attitude = {
							who = scope:overlord
							attitude = antagonistic
						}
						has_attitude = {
							who = scope:overlord
							attitude = domineering
						}
						has_attitude = {
