			}
		}
		else = {
			multiply = 0.5
		}

		# Multiplied by GDP per capita percentage
		if = {
			limit = {
				owner.gdp_per_capita_ranking >= 20 # TODO PRCAL-46014: change this out for the ratio of global average gdp per capita to gdp per capita
			}
			multiply = {
				value = 1
