				}
			}
			multiply = 0.1
		}
		multiply = {
			value = 1
			add = interest_group.modifier:interest_group_ideology_vanguardist_leader_chance_mult
			desc = "EVENTS_AND_OTHER_EFFECTS"
		}
	}
