		if = {
			limit = {
				has_dlc_feature = ip3_content
				scope:martyred_exile_scope ?= {
					has_template = aus_klemens_von_metternich
					is_immortal = yes
				}
			}
			set_character_immortal = no
		}
	}
	if = {
		limit = {
			owner ?= {
				NOT = {
					any_primary_culture = {
