capitulate_to_revolution = {
	scope:ongoing_revolution_movement = { #Can't trigger if they want governance reforms anyway.
		this.most_desired_law ?= {
			save_scope_as = revolutionaries_law
		}
	}
	every_interest_group = {
		limit = {
			is_insurrectionary = yes
		}
		set_variable = { name = revolutionary_ig days = 7 }
	}
	ordered_interest_group = {
		limit = {
			is_insurrectionary = yes
		}
		order_by = ig_clout
		position = 0
		check_range_bounds = no
		save_scope_as = revolution_leader_ig
	}
	activate_law = scope:revolutionaries_law

	every_interest_group = {
		limit = {
			has_variable = revolutionary_ig
		}
		owner = {
			add_loyalists = {
				value = 0.8
				interest_group = PREV
			}
		}
	}

	if = {
		limit = {
			country_has_voting_franchise = yes
			in_election_campaign = no
		}
		call_election = {
			months = 6
		}
	}
	if = {
		limit = {
			NOT = {
				has_law = law_type:law_monarchy
			}
		}
		hidden_effect = {
			scope:revolution_leader_ig = {
				leader = {
					set_character_as_ruler = yes
				}
			}
		}
	}

	every_interest_group = {
		limit = {
			is_in_government = yes
		}
		remove_ruling_interest_group = yes
		add_modifier = {
			name = modifier_revolution_defeated_light
			days = normal_modifier_time
			is_decaying = yes
		}
	}

	every_interest_group = {
		limit = {
			has_variable = revolutionary_ig
		}
		hidden_effect = {
			abandon_revolution = yes
		}
		add_modifier = {
			name = modifier_revolution_victorious_light
			days = normal_modifier_time
			is_decaying = yes
		}
		if = {
			limit = {
				is_insurrectionary = no
			}
			add_ruling_interest_group = yes
		}
	}
}

calculate_caudillo_progress = {
	set_variable = { name = caudillo_next value = 0 }
	if = {
		limit = {
			ig:ig_armed_forces ?= {
				is_powerful = yes
			}
		}
		change_variable = {
			name = caudillo_next
			add = 1
		}
	}
	if = {
		limit = {
			ig:ig_armed_forces ?= {
				is_in_government = yes
			}
		}
		change_variable = {
			name = caudillo_next
			add = 1
		}
	}
	if = {
		limit = {
			OR = {
				has_law_or_variant = law_type:law_autocracy
				has_law_or_variant = law_type:law_technocracy
				has_law_or_variant = law_type:law_oligarchy
				has_law_or_variant = law_type:law_single_party_state
			}
		}
		change_variable = {
			name = caudillo_next
			add = 1
		}
	}
	if = {
		limit = {
			ig:ig_armed_forces ?= {
				ig_counts_as_marginal = yes
			}
		}
		change_variable = {
			name = caudillo_next
			add = -1
		}
	}
	if = {
		limit = {
			ig:ig_armed_forces ?= {
				is_in_government = no
			}
		}
		change_variable = {
			name = caudillo_next
			add = -1
		}
	}
	if = {
		limit = {
			any_scope_character = {
				OR = {
					has_role_of_type = general
					has_role_of_type = admiral
				}
				popularity >= 50 # Loved
			}
		}
		change_variable = {
			name = caudillo_next
			add = 1
		}
	}
	if = {
		limit = {
			any_scope_character = {
				has_role_of_type = politician
				NOT = { has_role_of_type = general }
				popularity >= 50 # Loved
				interest_group ?= {
					is_powerful = yes
					AND = {
						law_stance = {
							law = law_type:law_autocracy
							value <= neutral
						}
						law_stance = {
							law = law_type:law_technocracy
							value >= neutral
						}
						law_stance = {
							law = law_type:law_oligarchy
							value >= neutral
						}
						law_stance = {
							law = law_type:law_single_party_state
							value >= neutral
						}
					}
				}
			}
			NOT = {
				any_scope_character = {
					has_role_of_type = general
					popularity >= 50 # Loved
				}
			}
		}
		change_variable = {
			name = caudillo_next
			add = -1
		}
	}
	if = {
		limit = {
			any_scope_character = {
				is_ruler_of_own_country = yes
				has_ideology = ideology:ideology_authoritarian
			}
		}
		change_variable = {
			name = caudillo_next
			add = 1
		}
	}
	if = {
		limit = {
			OR = {
				has_law_or_variant = law_type:law_census_voting
				has_law_or_variant = law_type:law_universal_suffrage
			}
		}
		change_variable = {
			name = caudillo_next
			add = -1
		}
	}
}

